    [JsonPropertyName("MaximumMudTemperatureDownhole")]
    public double? MaximumMudTemperatureDownhole { get; set; }

    /// <summary>
    /// The minimum pump pressure used during the run
    /// </summary>
    [JsonPropertyName("MinimumPumpPressure")]
    public double? MinimumPumpPressure { get; set; }

    /// <summary>
    /// The maximum pump pressure used during the run
    /// </summary>
    [JsonPropertyName("MaximumPumpPressure")]
    public double? MaximumPumpPressure { get; set; }

    /// <summary>
    /// The average pump pressure used during the run
    /// </summary>
    [JsonPropertyName("AveragePumpPressure")]
    public double? AveragePumpPressure { get; set; }

    /// <summary>
    /// The minimum flowrate at the bit during the run
    /// </summary>
    [JsonPropertyName("MinimumBitFlowrate")]
    public double? MinimumBitFlowrate { get; set; }

    /// <summary>
    /// The maximum flowrate at the bit during the run
    /// </summary>
    [JsonPropertyName("MaximumBitFlowrate")]
    public double? MaximumBitFlowrate { get; set; }

    /// <summary>
    /// The average flowrate at the bit during the run
    /// </summary>
    [JsonPropertyName("AverageBitFlowrate")]
    public double? AverageBitFlowrate { get; set; }

    /// <summary>
    /// The class of the drilling fluid.
    /// </summary>
    [RegularExpression(@"^[\w\-\.]+:reference-data\-\-MudClass:[\w\-\.\:\%]+:[0-9]*$")]
    [JsonPropertyName("MudClass")]
    public string MudClass { get; set; }

    /// <summary>
